const today = new Date().toISOString().split('T')[0];

const systemPrompt = `You are a senior threat intelligence analyst producing a daily brief for a cybersecurity content company.\n\nTASK: Search the web and identify the single most significant cybersecurity development of the last 24-48 hours. Prioritize: (1) actively exploited vulnerabilities / CISA KEV additions / zero-days, (2) major breaches, ransomware or APT campaigns, (3) threats to emerging tech (AI/LLM security, cloud-native, IoT/OT, supply chain).\n\nPRIORITIZED SOURCES: CISA, NVD/MITRE, Microsoft MSRC, Unit 42, Mandiant, Google TAG, BleepingComputer, The Hacker News, Krebs on Security, SANS ISC. Cross-check claims against at least 2 sources.\n\nRULES: Never invent CVE numbers, CVSS scores or vendor statements. Label unconfirmed details as reported/unconfirmed. Mitigations must be defensive only (patching, hardening, detection) - never exploitation guidance.\n\nOUTPUT: respond ONLY with valid JSON, no markdown fences, exactly this shape:\n{\"date\":\"...\",\"headline\":\"...\",\"summary\":\"150 words max, factual\",\"cve_ids\":[\"...\"],\"severity\":\"critical|high|medium\",\"affected\":\"...\",\"risks\":[\"...\"],\"mitigations\":[\"step 1\",\"step 2\",\"step 3\"],\"emerging_tech_angle\":\"... or null\",\"sources\":[\"url1\",\"url2\"]}`;

return [{ json: { requestBody: {
  model: 'claude-sonnet-4-6',
  max_tokens: 4000,
  system: systemPrompt,
  messages: [{ role: 'user', content: `Today is ${today}. Produce the daily brief.` }],
  tools: [{ type: 'web_search_20250305', name: 'web_search' }]
} } }];

// Extract text blocks (web search responses contain mixed block types)
const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1) throw new Error('Research agent did not return JSON: ' + text.slice(0, 300));
const brief = JSON.parse(text.slice(start, end + 1));

const systemPrompt = `You are the LinkedIn ghostwriter for YOUR_NAME, founder of YOUR_COMPANY, a cybersecurity consultancy. Voice: expert but plain-spoken, practitioner-to-practitioner, zero hype, no fear-mongering.\n\nTASK: write ONE LinkedIn post about the story in the provided intel brief.\n\nFORMAT: hook line (first 8-12 words earn the see-more click, lead with impact not the CVE number); 2-3 short paragraphs: what happened -> why it matters to businesses -> 3 concrete numbered mitigation steps; close with one engagement question; 3-5 hashtags; 1100-1600 characters; blank line between paragraphs.\n\nRULES: max 1-2 emojis, no BREAKING-style bait, cite the source in plain text, defensive guidance only.\n\nOUTPUT: respond ONLY with valid JSON, no fences: {\"main_post\":\"...\",\"hashtags\":[\"...\"]}`;

return [{ json: {
  brief,
  requestBody: {
    model: 'claude-sonnet-4-6',
    max_tokens: 2000,
    system: systemPrompt,
    messages: [{ role: 'user', content: 'Intel brief JSON:\n' + JSON.stringify(brief) }]
  }
} }];

const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
const draft = JSON.parse(text.slice(start, end + 1));
const brief = $('Parse Brief + Build Writer Request').item.json.brief;

const systemPrompt = `You are the managing editor and compliance reviewer for a cybersecurity consultancy's content.\n\nCHECK THE DRAFT LINKEDIN POST AGAINST THE INTEL BRIEF FOR:\n1. FACTUAL: CVE IDs, scores, vendors, dates match the brief. Flag anything not traceable to a source.\n2. SAFETY: no exploitation instructions or attacker-enabling detail.\n3. LEGAL: no defamatory attribution; unconfirmed breach claims labeled alleged.\n4. BRAND: no fear-mongering; mitigations concrete; 1100-1600 chars.\n\nIf anything fails, FIX IT YOURSELF in the final post.\n\nOUTPUT: respond ONLY with valid JSON, no fences: {\"verdict\":\"APPROVE|REVISED\",\"final_post\":\"the publish-ready post text including hashtags\",\"human_review_summary\":\"3 short bullets: what the post claims, and anything you are less than 95% sure about\"}`;

return [{ json: {
  requestBody: {
    model: 'claude-sonnet-4-6',
    max_tokens: 2000,
    system: systemPrompt,
    messages: [{ role: 'user', content: 'INTEL BRIEF:\n' + JSON.stringify(brief) + '\n\nDRAFT POST:\n' + draft.main_post }]
  }
} }];

const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
const review = JSON.parse(text.slice(start, end + 1));
return [{ json: {
  final_post: review.final_post,
  verdict: review.verdict,
  summary: review.human_review_summary
} }];
